def find_lcm(arr):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    lcm = arr[0]
    for i in arr[1:]:
        lcm = (lcm * i) // gcd(lcm, i)
    return lcm

# Test the function
