def longestBitonicSubsequence(arr):
    n = len(arr)
    # Initialize the arrays to store the length of longest bitonic subsequences ending at each position
    # from left and right
    left = [1] * n
    right = [1] * n

    # Compute the length of longest bitonic subsequences ending at each position from left
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                left[i] = max(left[i], left[j] + 1)

    # Compute the length of longest bitonic subsequences ending at each position from right
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                right[i] = max(right[i], right[j] + 1)

    # Find the maximum length of bitonic subsequences
    max_length = 0
    for i in range(n):
        max_length = max(max_length, left[i] + right[i] - 1)

    return max_length

# Test the function
arr = [1, 3, 5, 4, 7, 6, 8, 2, 9]
print("Length of longest bitonic subsequence is", longestBitonicSubsequence(arr))

def max_increasing_subsequence(arr):
    n = len(arr)
    dp = [[num] for num in arr]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and len(dp[i]) < len(dp[j]) + 1:
                dp[i] = dp[j] + [arr[i]]

    max_length = max(len(sub) for sub in dp)
    return sum(max_length)

